  if( msg->slot_capitalization && FD_UNLIKELY( !fd_pb_push_uint64( enc, 2U, msg->slot_capitalization ) ) ) return 0;
  if( FD_UNLIKELY( !fd_pb_push_bytes( enc, 3U, msg->bank_hash, 32UL ) ) ) return 0;
  if( msg->has_cost_tracker && FD_UNLIKELY( !fd_pb_enc_submsg( enc, 4U, &fd_exec_test_cost_tracker_t_msg, &msg->cost_tracker ) ) ) return 0;
  if( msg->has_leader_schedule && FD_UNLIKELY( !fd_pb_enc_submsg( enc, 5U, &fd_exec_test_leader_schedule_effects_t_msg, &msg->leader_schedule ) ) ) return 0;
  for( ulong i=0UL; i<msg->stake_delegations_count; i++ ) {
    if( FD_UNLIKELY( !fd_pb_enc_submsg( enc, 6U, &fd_exec_test_stake_delegation_t_msg, &msg->stake_delegations[ i ] ) ) ) return 0;
  }
